import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0017 — Importer: mappature per sorgente e limiti","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0017-importer-details.md","filePath":"adr/0017-importer-details.md"}'),n={name:"adr/0017-importer-details.md"};function r(c,e,d,l,s,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0017-—-importer-mappature-per-sorgente-e-limiti" tabindex="-1">ADR-0017 — Importer: mappature per sorgente e limiti <a class="header-anchor" href="#adr-0017-—-importer-mappature-per-sorgente-e-limiti" aria-label="Permalink to &quot;ADR-0017 — Importer: mappature per sorgente e limiti&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.5, §4.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>matrice §2.2.1 (Importer, P1); D-06; roadmap M6-WP4</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>L&#39;importer porta in un vault note di altre app. I file sorgente sono non fidati. Apple Notes è rinviato a P2. Le fixture in <code>internal/importer/testdata</code> sono scritte a mano dalla conoscenza dei formati, non sono export reali.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Architettura.</strong> <code>internal/importer</code>: interfaccia <code>Importer{ID, Detect, Preview, Run}</code> + registry. Preview esegue lo stesso codice di Run su un sink &quot;dry-run&quot;, quindi conteggi e avvisi coincidono con l&#39;import. Le scritture passano da un <code>Sink</code> sul livello <code>vault.FS</code> (percorsi <code>pathrules</code>, scrittura atomica, contenimento symlink); i nomi sono prenotati prima della scrittura e non sovrascrivono mai (suffisso <code> (1)</code>). Destinazione predefinita <code>Imports/&lt;sorgente&gt;-&lt;data&gt;/</code>; al termine viene scritta la nota <code>Import report.md</code> nella stessa cartella. Binding <code>ImporterAPI</code> (eventi <code>importer:progress</code>/<code>importer:done</code>, un solo import per vault, rifiutato sui mount viewer). L&#39;indicizzazione è affidata al watcher.</p><p><strong>Link.</strong> I link Markdown relativi (anche con percent-encoding, spazi, <code>#ancora</code>) sono riscritti in <code>[[wikilink]]</code>/embed se l&#39;opzione <code>useWikilinks</code> è attiva (nome breve se univoco tra i file importati, altrimenti percorso), altrimenti restano link Markdown con percorso corretto. Codice inline e blocchi di codice non vengono toccati. Link a file non importati restano invariati e sono contati nel report. <code>useWikilinks</code> e cartella allegati sono opzioni del wizard (non esistono ancora come impostazioni di vault).</p><p><strong>Allegati.</strong> Le sorgenti &quot;cartella&quot; (Markdown, Notion) mantengono la struttura relativa; gli allegati generati (ENEX, Keep, Bear) vanno in <code>&lt;destinazione&gt;/attachments</code>. Se la cartella allegati è impostata, tutti gli allegati vanno lì.</p><p><strong>Per sorgente.</strong></p><ul><li><em>Markdown/HTML</em>: <code>.md</code> copiati, <code>.html</code> convertiti, altri file come allegati; cartelle nascoste ignorate.</li><li><em>ENEX</em>: <code>created</code>/<code>updated</code>/<code>tags</code>/<code>source</code>/<code>author</code> nel frontmatter; ENML→Markdown (<code>en-todo</code>→task, <code>en-media</code> per hash MD5, <code>en-crypt</code> sostituito da un callout con avviso); risorse base64 con estensione da MIME.</li><li><em>Notion</em>: via suffisso id a 32 hex da nomi di file e cartelle, <code>_all.csv</code> ignorato se esiste il CSV base, cartella-radice unica rimossa; ogni CSV genera una nota indice (tabella con link) e le proprietà finiscono nel frontmatter della pagina della riga (o in una nuova nota se la pagina manca). Archivi annidati non sono aperti (avviso).</li><li><em>Roam</em>: blocchi→elenchi annidati (tab), <code>{{[[TODO]]}}</code>/<code>DONE</code>→task, <code>((uid))</code>→testo semplice (avviso; irrisolti rimossi), <code>^^x^^</code>→<code>==x==</code>, <code>#[[x]]</code>→<code>[[x]]</code>, titoli giornalieri→<code>YYYY-MM-DD</code> (tag <code>daily-note</code>), <code>/</code> nei titoli→<code>-</code> con alias nei link. Altri <code>{{componenti}}</code> restano testo.</li><li><em>Bear</em>: <code>.bearbk</code>, <code>.textbundle/.textpack</code> (cartella o zip), Markdown esportato; tag in frontmatter, <code>#multi word#</code>→<code>#multi-word</code>, date da <code>info.json</code>. Il formato <code>[image:…]</code> (backup vecchi) non è risolto (avviso).</li><li><em>Google Keep</em>: JSON di Takeout; liste→task, label→<code>tags</code>, <code>pinned</code>/<code>archived</code>/<code>trashed</code>/<code>color</code> come proprietà, archiviate e cestinate escluse salvo opzione. Le pagine HTML di Takeout sono lette quando una nota non ha il JSON accanto (esportazioni vecchie o parziali): stesso risultato, con il contenuto convertito da HTML e la data della pagina come <code>updated</code> (ora locale della macchina che importa; manca <code>created</code>). Una nota presente in entrambi i formati è letta dal JSON.</li><li><em>CSV</em>: delimitatore rilevato (<code>, ; tab |</code>), colonna titolo e corpo scelte dall&#39;utente, le altre in frontmatter con inferenza di tipo (numero, booleano, data); <code>tags</code>/<code>aliases</code> come liste.</li></ul><p><strong>Sicurezza.</strong> Nomi di voci zip validati (no assoluti, <code>..</code>, <code>\\</code>, NUL, unità) e mai usati come percorso di destinazione; tetto a numero di voci (200.000), byte dichiarati (8 GiB) e per file (1 GiB), più un lettore che applica i tetti ai byte realmente letti (header falsi); symlink ignorati. XML con <code>encoding/xml</code> (nessuna entità esterna/DTD; le entità personalizzate danno errore) su lettore a dimensione limitata. HTML → Markdown puro: <code>script</code>, <code>style</code>, <code>iframe</code>, <code>object</code>, form, handler e stili sono scartati (e segnalati), link <code>javascript:</code>/<code>data:</code> ridotti al testo.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Un&#39;implementazione per Preview e una per Run</strong> — scartata: i conteggi divergerebbero.</li><li><strong>Mantenere HTML grezzo nelle note</strong> — scartata: V-02 vieta HTML/CSS attivo.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Limiti noti: dati reali non verificati; Apple Notes (P2); Notion senza i valori delle relazioni risolti; la conversione HTML non riproduce layout complessi. I wikilink brevi sono univoci solo tra i file importati, non rispetto al resto del vault.</p>',15)])])}const g=o(n,[["render",r]]);export{u as __pageData,g as default};
